/**
* Traditional Chinese — Hong Kong (zh-HK) translations for all DSH built-in
* i18n namespaces. Generated from the zh source dictionaries in the DSH
* source tree.
*
* Hong Kong regional conventions:
* - 软件 → 軟件 (NOT 軟體)
* - 网络 → 網絡 (NOT 網路)
* - 鼠标 → 滑鼠
* - 檔案 (file), 資料夾 (folder), 程式 (program), 螢幕 (screen)
* - 預設 (default), 儲存 (save)
* - session (会话) → 工作階段; chat (对话) → 對話
* - refresh (刷新) → 重新整理; cache (缓存) → 快取
* - timeout (超时) → 逾時; loop (循环) → 迴圈
* - read-only (只读) → 唯讀; override (覆盖) → 覆寫
* - adapter (适配器) → 介面卡; interface (接口) → 介面
* - address (地址) → 位址; field (字段) → 欄位
* - byte (字节) → 位元組; character (字符) → 字元
* - rename (重命名) → 重新命名; archive (归档) → 歸檔
* - idle (空闲) → 閒置; mount (挂载) → 掛載
* - package (包) → 套件; code (代码) → 程式碼
* - generate (生成) → 產生; fetch/get (获取) → 取得
* - export (导出) → 匯出; configure (配置) → 設定
* - quotation marks: "" → 「」
*/
